// Story medal targets live in the map, alongside route-specific devices.
function renderStoryMedalSettings(){const story=!editorChallengeId();$('editorStoryMedals').classList.toggle('hidden',!story);if(!story)return;const t=editorMap.medalTargets||medalTargets[editorTarget()];$('editorMedalGold').value=t.gold;$('editorMedalSilver').value=t.silver;$('editorMedalStatus').textContent='맵과 함께 저장되며 스테이지 선택·결과 화면에 반영됩니다.';}
function applyStoryMedalSettings(){if(editorChallengeId())return true;try{const target={gold:Number($('editorMedalGold').value),silver:Number($('editorMedalSilver').value)};normalizeMapExtras(editorMap,{medalTargets:target});if(JSON.stringify(target)!==JSON.stringify(editorMap.medalTargets)){editorSnapshot();editorMap.medalTargets=target;}return true;}catch(e){$('editorMedalStatus').textContent=e.message;return false;}}
for(const id of ['editorMedalGold','editorMedalSilver'])$(id).onchange=applyStoryMedalSettings;
for(const id of ['editorSave','editorQuickSave','editorTest','editorTestPage']){const before=$(id).onclick;$(id).onclick=(...args)=>{if(!applyStoryMedalSettings()){closeEditorSheets();$('editorSettingsPanel').classList.remove('hidden');return false;}return before?.(...args);};}
const rulesSettingsOpen=$('editorSettingsOpen').onclick;$('editorSettingsOpen').onclick=()=>{const out=rulesSettingsOpen();renderStoryMedalSettings();return out;};
for(const [value,text]of [['gravityGate','중력 변환 장치'],['gravityGateRemove','중력 장치 제거'],['finishRemove','FINISH 제거']]){const o=document.createElement('option');o.value=value;o.textContent=text;$('editorBrush').appendChild(o);}
let pendingGravityDevice=null;
function closeGravityDevice(){pendingGravityDevice=null;$('gravityDeviceDialog').classList.add('hidden');}
$('gravityDeviceCancel').onclick=closeGravityDevice;
$('gravityDeviceApply').onclick=()=>{const p=pendingGravityDevice;if(!p||p.map!==editorMap)return closeGravityDevice();const gravity=Number($('gravityDeviceValue').value);try{const gates=(editorMap.gravityGates||[]).filter(g=>g.row!==p.row||g.lane!==p.lane);gates.push({row:p.row,lane:p.lane,gravity});normalizeMapExtras(editorMap,{gravityGates:gates});editorSnapshot();editorMap.gravityGates=gates;closeGravityDevice();renderEditorGrid();$('editorStatus').textContent='중력 변환 장치 '+gravity+' 배치됨 · 저장 후 적용됩니다.';}catch(e){$('gravityDeviceLocation').textContent=e.message;}};
const devicePaint=paintEditorCell;paintEditorCell=function(r,l,batch=false){const brush=$('editorBrush').value;
 if(brush==='gravityGate'){
  if(pendingGravityDevice)return;
  if(r<3||![1,3,4,5].includes(editorMap.tiles[r][l])||editorMap.roadPaint[r][l]==='pink'){$('editorStatus').textContent='중력 장치는 4번째 줄 이후 안전한 도로에 배치하세요.';return;}
  pendingGravityDevice={map:editorMap,row:r,lane:l};$('gravityDeviceValue').value=String(editorMap.gravityGates?.find(g=>g.row===r&&g.lane===l)?.gravity||100);$('gravityDeviceLocation').textContent=(r+1)+'줄 · '+(l+1)+'칸';$('gravityDeviceDialog').classList.remove('hidden');return;
 }
 if(brush==='gravityGateRemove'||brush==='finishRemove'){if(!batch)editorSnapshot();if(brush==='gravityGateRemove')editorMap.gravityGates=(editorMap.gravityGates||[]).filter(g=>g.row!==r||g.lane!==l);else{editorMap.finishes=mapFinishes(editorMap).filter(f=>f.row!==r||f.lane!==l);editorMap.finish=editorMap.finishes.at(-1);}if(!batch)renderEditorGrid();return;}
 const out=devicePaint(r,l,batch);if(editorMap.gravityGates)editorMap.gravityGates=editorMap.gravityGates.filter(g=>[1,3,4,5].includes(editorMap.tiles[g.row]?.[g.lane])&&editorMap.roadPaint[g.row][g.lane]!=='pink');if(!batch)renderEditorGrid();return out;
};
const deviceStroke=editorStrokeCell;editorStrokeCell=function(r,l){if($('editorBrush').value==='gravityGate'){if(!pendingGravityDevice)paintEditorCell(r,l);return;}return deviceStroke(r,l);};
const deviceFill=$('editorFillPage').onclick;$('editorFillPage').onclick=()=>{if($('editorBrush').value==='gravityGate'){$('editorStatus').textContent='중력 장치는 한 칸씩 눌러 수치를 지정하세요.';return;}return deviceFill();};
const rulesGrid=renderEditorGrid;renderEditorGrid=function(...args){const out=rulesGrid(...args);renderStoryMedalSettings();for(const cell of $('editorGrid').children||[]){if(!cell.getAttribute||cell.getAttribute('data-editor-row')===null)continue;const r=Number(cell.getAttribute('data-editor-row')),l=Number(cell.getAttribute('data-editor-lane')),gate=editorMap.gravityGates?.find(g=>g.row===r&&g.lane===l);if(gate){cell.classList.add('gravity-device-cell');cell.textContent='G'+gate.gravity;cell.title='중력 변환 → '+gate.gravity;cell.setAttribute('aria-label',(r+1)+'줄 '+(l+1)+'칸 중력 변환 '+gate.gravity);}}return out;};
const rulesResize=$('editorResize').onclick;$('editorResize').onclick=()=>{const before=editorMap,extra={medalTargets:before.medalTargets,gravityGates:before.gravityGates,finishes:mapFinishes(before)};const out=rulesResize();if(editorMap!==before){if(extra.medalTargets)editorMap.medalTargets={...extra.medalTargets};editorMap.gravityGates=(extra.gravityGates||[]).filter(g=>g.row<editorMap.tiles.length);editorMap.finishes=extra.finishes.filter(f=>f.row<editorMap.tiles.length);editorMap.finish=editorMap.finishes.at(-1);renderEditorGrid();}return out;};
let runGravityOverride=null;
const gateBegin=beginRun;beginRun=function(...args){runGravityOverride=null;return gateBegin(...args);};start=beginRun;
const gateGravityValue=gravityValue;gravityValue=function(){return mode==='story'&&runGravityOverride!==null?runGravityOverride:gateGravityValue();};
const gateStep=step;step=function(dt){if(dt>1/120+.000001){const n=Math.ceil(dt/(1/120));for(let i=0;i<n;i++)step(dt/n);return;}const oldZ=z,oldX=x,playing=state==='play',out=gateStep(dt);if(playing&&mode==='story'&&state==='play')for(const gate of activeRoadData().gravityGates||[]){const goal=gate.row+.5;if(oldZ<goal&&z>=goal){const q=(goal-oldZ)/(z-oldZ),px=oldX+(x-oldX)*q;if(Math.floor(px+3.5)===gate.lane){runGravityOverride=gate.gravity;$('gravity').textContent=gate.gravity;}}}return out;};
const gravityGateLookups=new WeakMap();
function gravityGateAt(map,r,l){const gates=map.gravityGates;if(!gates)return null;let lookup=gravityGateLookups.get(gates);if(!lookup){lookup=new Map(gates.map(g=>[g.row+':'+g.lane,g]));gravityGateLookups.set(gates,lookup);}return lookup.get(r+':'+l);}
const gatePickup=drawRoadPickup;drawRoadPickup=function(r,l,t){gatePickup(r,l,t);if(!t)return;const gate=gravityGateAt(activeRoadData(),r,l);if(!gate)return;const a=l-roadOffset();ctx.save();releaseGroundQuad(a+.06,a+.94,r+.12,r+.88,.025,'#2b6578');releaseGroundQuad(a+.10,a+.90,r+.42,r+.58,.028,'#a8efff');const p=proj(l-3,r+.5,.6);if(p[2]>7&&r-z<40){ctx.font='bold '+Math.min(24,p[2]*.21)+'px sans-serif';ctx.textAlign='center';ctx.fillStyle='#c2f6ff';ctx.fillText('G '+gate.gravity,p[0],p[1]);}ctx.restore();};
renderStoryMedalSettings();
